// Normalize direct WF03/WF98 invocation and protected webhook input
// into one plain payload object.

const input = $json ?? {};

const payload =
  input.body !== null &&
  typeof input.body === 'object' &&
  !Array.isArray(input.body)
    ? input.body
    : input;

return {
  json: payload,
};

// Validate and normalize the authoritative WF04 invocation contract.

const input = $json ?? {};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function requireUuid(value, fieldName) {
  if (typeof value !== 'string') {
    throw new Error(`${fieldName} must be a UUID string`);
  }

  const normalized = value.trim().toLowerCase();

  if (!UUID_PATTERN.test(normalized)) {
    throw new Error(`${fieldName} must be a valid UUID`);
  }

  return normalized;
}

function optionalUuid(value, fieldName) {
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  ) {
    return null;
  }

  return requireUuid(value, fieldName);
}

function optionalText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized = String(value).trim();

  return normalized === '' ? null : normalized;
}

const triggerSource = String(
  input.trigger_source ?? '',
)
  .trim()
  .toLowerCase();

if (
  triggerSource !== 'wf03' &&
  triggerSource !== 'wf98'
) {
  throw new Error(
    'trigger_source must be wf03 or wf98',
  );
}

const caseId = requireUuid(
  input.case_id,
  'case_id',
);

const correlationId = requireUuid(
  input.correlation_id,
  'correlation_id',
);

const acceptedSubmissionId = optionalUuid(
  input.accepted_submission_id,
  'accepted_submission_id',
);

const clientId = optionalUuid(
  input.client_id,
  'client_id',
);

const externalOperationId = optionalUuid(
  input.external_operation_id,
  'external_operation_id',
);

const recoveryReason = optionalText(
  input.recovery_reason,
);

if (triggerSource === 'wf03') {
  if (
    acceptedSubmissionId === null ||
    clientId === null
  ) {
    throw new Error(
      'WF03 invocation requires accepted_submission_id and client_id',
    );
  }

  if (
    externalOperationId !== null ||
    recoveryReason !== null
  ) {
    throw new Error(
      'WF03 invocation must not contain recovery fields',
    );
  }
}

if (triggerSource === 'wf98') {
  if (
    acceptedSubmissionId !== null ||
    clientId !== null
  ) {
    throw new Error(
      'WF98 invocation must not contain WF03 identity fields',
    );
  }

  if (
    externalOperationId === null &&
    recoveryReason !== 'missing_initial_dispatch'
  ) {
    throw new Error(
      'WF98 invocation requires external_operation_id or missing_initial_dispatch recovery',
    );
  }

  if (
    externalOperationId !== null &&
    recoveryReason !== null
  ) {
    throw new Error(
      'WF98 operation retry and state-gap recovery are mutually exclusive',
    );
  }
}

return {
  json: {
    case_id: caseId,
    correlation_id: correlationId,
    trigger_source: triggerSource,
    accepted_submission_id: acceptedSubmissionId,
    client_id: clientId,
    external_operation_id: externalOperationId,
    recovery_reason: recoveryReason,
  },
};

// Validate WF04 runtime configuration and build a deterministic
// approval request context shared by initial dispatch and retries.

const crypto = require('crypto');
const input = $json ?? {};

function requireText(value, fieldName) {
  const normalized = String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(`${fieldName} must not be blank`);
  }

  return normalized;
}

function readInteger(name, minimum, maximum) {
  const rawValue = requireText(
    $env[name],
    name,
  );

  const value = Number(rawValue);

  if (
    !Number.isInteger(value) ||
    value < minimum ||
    value > maximum
  ) {
    throw new Error(
      `${name} must be an integer between ${minimum} and ${maximum}`,
    );
  }

  return value;
}

const recipientEmail = requireText(
  $env.APPROVAL_RECIPIENT_EMAIL,
  'APPROVAL_RECIPIENT_EMAIL',
).toLowerCase();

if (
  !/^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/.test(
    recipientEmail,
  )
) {
  throw new Error(
    'APPROVAL_RECIPIENT_EMAIL is invalid',
  );
}

const templateKey = requireText(
  $env.APPROVAL_TEMPLATE_KEY,
  'APPROVAL_TEMPLATE_KEY',
);

if (templateKey !== 'manual_approval_v1') {
  throw new Error(
    'APPROVAL_TEMPLATE_KEY must equal manual_approval_v1',
  );
}

const responseTimeoutHours = readInteger(
  'APPROVAL_RESPONSE_TIMEOUT_HOURS',
  1,
  720,
);

const leaseSeconds = readInteger(
  'WF04_OPERATION_LEASE_SECONDS',
  1,
  2592000,
);

if (
  leaseSeconds <=
  responseTimeoutHours * 3600
) {
  throw new Error(
    'WF04_OPERATION_LEASE_SECONDS must exceed the approval response timeout',
  );
}

const maxAttempts = readInteger(
  'WF04_OPERATION_MAX_ATTEMPTS',
  1,
  20,
);

const waitingExecutionId = requireText(
  $execution.id,
  'execution_id',
);

const messageMarker =
  'b2b-approval-' +
  crypto
    .createHash('sha256')
    .update(input.case_id)
    .digest('hex')
    .slice(0, 24);

return {
  json: {
    ...input,

    waiting_execution_id:
      waitingExecutionId,

    recipient_email:
      recipientEmail,

    template_key:
      templateKey,

    message_marker:
      messageMarker,

    response_timeout_hours:
      responseTimeoutHours,

    lease_seconds:
      leaseSeconds,

    max_attempts:
      maxAttempts,

    sender_name:
      requireText(
        $env.APPROVAL_REQUEST_SENDER_NAME,
        'APPROVAL_REQUEST_SENDER_NAME',
      ),

    support_contact:
      String(
        $env.APPROVAL_SUPPORT_CONTACT ?? '',
      ).trim() || null,
  },
};

// Normalize the authoritative PostgreSQL preparation result
// before routing WF04 to sending, no-op, or intervention.

const row = $json ?? {};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function requireText(value, fieldName) {
  const normalized = String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(`${fieldName} must not be blank`);
  }

  return normalized;
}

function optionalText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized = String(value).trim();

  return normalized === '' ? null : normalized;
}

function optionalUuid(value, fieldName) {
  const normalized = optionalText(value);

  if (normalized === null) {
    return null;
  }

  if (!UUID_PATTERN.test(normalized)) {
    throw new Error(`${fieldName} must be a valid UUID`);
  }

  return normalized.toLowerCase();
}

const inputContext =
  isPlainObject(row.input_context)
    ? row.input_context
    : {};

const preparationOutcome = requireText(
  row.preparation_outcome,
  'preparation_outcome',
);

const operationClaimOutcome = optionalText(
  row.operation_claim_outcome,
);

const operationId = optionalUuid(
  row.operation_id,
  'operation_id',
);

const caseId =
  optionalUuid(
    row.case_id,
    'case_id',
  ) ??
  optionalUuid(
    inputContext.case_id,
    'input_context.case_id',
  );

const correlationId =
  optionalUuid(
    row.correlation_id,
    'correlation_id',
  ) ??
  optionalUuid(
    inputContext.correlation_id,
    'input_context.correlation_id',
  );

let preparationDecision;

if (preparationOutcome === 'ready_to_send') {
  if (
    operationClaimOutcome !== 'claimed' ||
    operationId === null ||
    row.operation_status !== 'in_progress' ||
    row.approval_step_status !== 'waiting'
  ) {
    throw new Error(
      'ready_to_send returned an inconsistent operation state',
    );
  }

  preparationDecision = 'send_approval_request';

} else if (
  preparationOutcome === 'active_wait_exists'
) {
  if (
    operationClaimOutcome !== 'busy' ||
    operationId === null ||
    row.operation_status !== 'in_progress' ||
    row.approval_step_status !== 'waiting'
  ) {
    throw new Error(
      'active_wait_exists returned an inconsistent operation state',
    );
  }

  preparationDecision = 'no_action';

} else if (
  [
    'already_approved',
    'already_rejected',
    'not_required',
    'not_due',
  ].includes(preparationOutcome)
) {
  preparationDecision = 'no_action';

} else {
  preparationDecision =
    'operator_intervention_required';
}

const waitingExecutionId = optionalText(
  row.waiting_execution_id ??
  inputContext.waiting_execution_id,
);

return {
  json: {
    workflow: 'WF04',

    preparation_decision:
      preparationDecision,

    preparation_outcome:
      preparationOutcome,

    operation_claim_outcome:
      operationClaimOutcome,

    operation_id:
      operationId,

    operation_status:
      optionalText(row.operation_status),

    operation_attempt_count:
      row.operation_attempt_count ?? null,

    operation_max_attempts:
      row.operation_max_attempts ?? null,

    operation_lease_expires_at:
      row.operation_lease_expires_at ?? null,

    case_id:
      caseId,

    correlation_id:
      correlationId,

    case_state:
      optionalText(row.case_state),

    accepted_submission_id:
      optionalUuid(
        row.accepted_submission_id,
        'accepted_submission_id',
      ),

    client_id:
      optionalUuid(
        row.client_id,
        'client_id',
      ),

    approval_step_id:
      optionalUuid(
        row.approval_step_id,
        'approval_step_id',
      ),

    approval_step_status:
      optionalText(row.approval_step_status),

    waiting_execution_id:
      waitingExecutionId,

    lease_owner:
      waitingExecutionId === null
        ? null
        : `WF04:${waitingExecutionId}`,

    recipient_email:
      optionalText(row.recipient_email),

    response_timeout_hours:
      row.response_timeout_hours ?? null,

    template_key:
      optionalText(row.template_key),

    message_marker:
      optionalText(row.message_marker),

    legal_name:
      optionalText(row.legal_name),

    company_identifier_country:
      optionalText(
        row.company_identifier_country,
      ),

    company_identifier_type:
      optionalText(
        row.company_identifier_type,
      ),

    company_identifier_value:
      optionalText(
        row.company_identifier_value,
      ),

    primary_contact_first_name:
      optionalText(
        row.primary_contact_first_name,
      ),

    primary_contact_last_name:
      optionalText(
        row.primary_contact_last_name,
      ),

    primary_contact_email:
      optionalText(
        row.primary_contact_email,
      ),

    primary_contact_phone:
      optionalText(
        row.primary_contact_phone,
      ),

    case_created_at:
      row.case_created_at ?? null,

    trigger_source:
      optionalText(inputContext.trigger_source),

    sender_name:
      optionalText(inputContext.sender_name),

    support_contact:
      optionalText(inputContext.support_contact),
  },
};

// Return a clean idempotent result when WF04 must not send
// another approval request.

const input = $json ?? {};

if (input.preparation_decision !== 'no_action') {
  throw new Error(
    'Return No Action Result received an invalid preparation decision',
  );
}

return {
  json: {
    workflow: 'WF04',

    result: 'no_action',

    preparation_outcome:
      input.preparation_outcome ?? null,

    case_id:
      input.case_id ?? null,

    correlation_id:
      input.correlation_id ?? null,

    operation_id:
      input.operation_id ?? null,

    case_state:
      input.case_state ?? null,

    approval_step_status:
      input.approval_step_status ?? null,
  },
};

// Build a plain-text approval email only from
// authoritative PostgreSQL data.

const input = $json ?? {};

function requireText(value, fieldName) {
  const normalized =
    String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  return normalized;
}

function displayValue(value) {
  const normalized =
    String(value ?? '').trim();

  return normalized === ''
    ? 'Not provided'
    : normalized;
}

if (
  input.preparation_decision !==
  'send_approval_request'
) {
  throw new Error(
    'Build Approval Email received an invalid preparation decision',
  );
}

const caseId = requireText(
  input.case_id,
  'case_id',
);

const operationId = requireText(
  input.operation_id,
  'operation_id',
);

const recipientEmail = requireText(
  input.recipient_email,
  'recipient_email',
);

const legalName = requireText(
  input.legal_name,
  'legal_name',
);

const identifier = [
  input.company_identifier_country,
  input.company_identifier_type,
  input.company_identifier_value,
]
  .filter(
    (value) =>
      value !== null &&
      value !== undefined &&
      String(value).trim() !== '',
  )
  .join(' / ');

const contactName = [
  input.primary_contact_first_name,
  input.primary_contact_last_name,
]
  .filter(
    (value) =>
      value !== null &&
      value !== undefined &&
      String(value).trim() !== '',
  )
  .join(' ');

const approvalSubject =
  `Approval required: ${legalName}`;

const messageLines = [
  'Manual onboarding approval required',
  '',
  'Review the validated client information below.',
  'Select Approve or Reject using the buttons in this email.',
  '',
  `Company: ${legalName}`,
  `Company identifier: ${displayValue(identifier)}`,
  `Primary contact: ${displayValue(contactName)}`,
  `Contact email: ${displayValue(input.primary_contact_email)}`,
  `Contact phone: ${displayValue(input.primary_contact_phone)}`,
  '',
  `Case ID: ${caseId}`,
  `Operation ID: ${operationId}`,
  `Message marker: ${displayValue(input.message_marker)}`,
];

if (input.support_contact) {
  messageLines.push(
    '',
    `Support: ${input.support_contact}`,
  );
}

return {
  json: {
    ...input,

    approval_recipient:
      recipientEmail,

    approval_subject:
      approvalSubject,

    approval_message:
      messageLines.join('\n'),
  },
};

// Normalize the Gmail approval response without relying
// on data from nodes that executed before the wait.

const input = $json ?? {};

function optionalText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized =
    String(value).trim();

  return normalized === ''
    ? null
    : normalized;
}

const approved =
  typeof input?.data?.approved === 'boolean'
    ? input.data.approved
    : typeof input.approved === 'boolean'
      ? input.approved
      : typeof input?.response?.approved === 'boolean'
        ? input.response.approved
        : null;

if (approved === null) {
  throw new Error(
    'Gmail approval response does not contain a boolean approved value',
  );
}

const waitingExecutionId =
  String($execution.id ?? '').trim();

if (waitingExecutionId === '') {
  throw new Error(
    'Current n8n execution ID is unavailable',
  );
}

return {
  json: {
    workflow:
      'WF04',

    waiting_execution_id:
      waitingExecutionId,

    lease_owner:
      `WF04:${waitingExecutionId}`,

    decision:
      approved
        ? 'approved'
        : 'rejected',

    responded_at:
      new Date().toISOString(),

    gmail_message_id:
      optionalText(
        input?.data?.messageId ??
        input?.data?.message_id ??
        input?.messageId ??
        input?.message_id,
      ),

    gmail_thread_id:
      optionalText(
        input?.data?.threadId ??
        input?.data?.thread_id ??
        input?.threadId ??
        input?.thread_id,
      ),

    operator_comment:
      optionalText(
        input?.data?.comment ??
        input?.data?.text ??
        input?.comment,
      ),

    response_source:
      'n8n_send_and_wait',
  },
};

// Validate the authoritative WF04 finalization result
// and determine the next workflow action.

const input = $json ?? {};

const result =
  input.finalization_result;

if (
  result === null ||
  typeof result !== 'object' ||
  Array.isArray(result)
) {
  throw new Error(
    'finalization_result must be a JSON object',
  );
}

const lookupOutcome =
  String(
    result.context_lookup_outcome ?? '',
  ).trim();

const finalizationOutcome =
  String(
    result.finalization_outcome ?? '',
  ).trim();

const decision =
  String(
    result.decision ??
    result.final_decision ??
    '',
  ).trim();

let nextAction;

if (
  lookupOutcome === 'context_resolved' &&
  finalizationOutcome === 'finalized'
) {
  if (
    result.final_step_status !== 'completed' ||
    result.final_operation_status !== 'succeeded'
  ) {
    throw new Error(
      'Finalized WF04 response returned inconsistent terminal state',
    );
  }

  if (
    decision === 'approved' &&
    result.final_case_state === 'approved'
  ) {
    nextAction =
      'dispatch_wf05';

  } else if (
    decision === 'rejected' &&
    result.final_case_state === 'rejected'
  ) {
    nextAction =
      'complete_rejected';

  } else {
    throw new Error(
      'WF04 decision does not match the finalized case state',
    );
  }

} else if (
  lookupOutcome === 'context_resolved' &&
  finalizationOutcome === 'already_finalized'
) {
  nextAction =
    'no_action';

} else {
  nextAction =
    'operator_intervention_required';
}

return {
  json: {
    workflow:
      'WF04',

    next_action:
      nextAction,

    context_lookup_outcome:
      lookupOutcome || null,

    finalization_outcome:
      finalizationOutcome || null,

    case_id:
      result.case_id ?? null,

    operation_id:
      result.operation_id ?? null,

    waiting_execution_id:
      result.waiting_execution_id ?? null,

    decision:
      decision || null,

    final_case_state:
      result.final_case_state ?? null,

    final_step_status:
      result.final_step_status ?? null,

    final_operation_status:
      result.final_operation_status ?? null,

    final_client_id:
      result.final_client_id ?? null,

    final_accepted_submission_id:
      result.final_accepted_submission_id ?? null,
  },
};

// Return the terminal WF04 result after a valid rejection.

const input = $json ?? {};

if (input.next_action !== 'complete_rejected') {
  throw new Error(
    'Return Rejected Result received an invalid next action',
  );
}

if (
  input.decision !== 'rejected' ||
  input.final_case_state !== 'rejected' ||
  input.final_step_status !== 'completed' ||
  input.final_operation_status !== 'succeeded'
) {
  throw new Error(
    'Rejected WF04 result contains an inconsistent terminal state',
  );
}

return {
  json: {
    workflow: 'WF04',
    result: 'rejected',

    case_id:
      input.case_id ?? null,

    operation_id:
      input.operation_id ?? null,

    decision:
      input.decision,

    case_state:
      input.final_case_state,

    approval_step_status:
      input.final_step_status,

    operation_status:
      input.final_operation_status,
  },
};

// Return an idempotent result when this approval response
// was already finalized previously.

const input = $json ?? {};

if (input.next_action !== 'no_action') {
  throw new Error(
    'Return Finalization No Action Result received an invalid next action',
  );
}

return {
  json: {
    workflow: 'WF04',
    result: 'no_action',

    finalization_outcome:
      input.finalization_outcome ?? null,

    case_id:
      input.case_id ?? null,

    operation_id:
      input.operation_id ?? null,

    decision:
      input.decision ?? null,

    case_state:
      input.final_case_state ?? null,
  },
};
